insert into public.products (id,name,slug,category,gender,description,price,original_price,is_sale,is_featured,is_new_arrival,images,sizes,stock,sku,details,materials) values ('prod-1', 'Atelier Bespoke Cashmere Overcoat', 'atelier-bespoke-cashmere-overcoat', 'Jackets', 'Unisex', 'Constructed from triple-weight Italian virgin cashmere and double-faced Melton wool. Features sharp architectural lapels, hand-stitched horn buttons, and an elongated minimalist silhouette crafted for supreme warmth and poise.', 85000, 110000, true, true, true, array['/src/assets/images/zhar_luxury_jacket_1794080538698.jpg']::text[], array['S','M','L','XL']::text[], 7, 'ZHR-JKT-001', array['100% Grade-A Italian Virgin Cashmere','Structural floating canvas interlining','Matte horn buttons hand-dyed in Florence','Internal hidden passport & card pocket','Specialist dry clean only']::text[], 'Virgin Cashmere & Italian Cupro Lining') on conflict (id) do nothing;
insert into public.products (id,name,slug,category,gender,description,price,original_price,is_sale,is_featured,is_new_arrival,images,sizes,stock,sku,details,materials) values ('prod-2', 'Noir Smoked Extrait de Parfum (100ml)', 'noir-smoked-extrait-de-parfum', 'Perfumes', 'Unisex', 'A deep olfactory journey through cold incense, dark birch tar, smoked vetiver, and black agarwood. Encased in a monolithic smoked-glass flacon weighted with a machined matte black aluminum cap.', 32000, null, false, true, true, array['/src/assets/images/zhar_luxury_perfume_1794080536268.jpg']::text[], array['100ml Extrait']::text[], 14, 'ZHR-FRG-002', array['38% Extrait de Parfum concentration','Top Notes: Cold Pink Pepper, Smoked Birch','Heart Notes: Black Incense, Orris Butter','Base Notes: Rare Oud Wood, Spanish Cistus, Dark Amber','Macerated for 90 days in Grasse, France']::text[], 'Natural Botanicals & Artisanal Essences') on conflict (id) do nothing;
insert into public.products (id,name,slug,category,gender,description,price,original_price,is_sale,is_featured,is_new_arrival,images,sizes,stock,sku,details,materials) values ('prod-3', 'Chrono Noir Matte Titanium Timepiece', 'chrono-noir-matte-timepiece', 'Watches', 'Men', 'Architected with a Grade 5 titanium case coated in deep obsidian DLC (Diamond-Like Carbon). Features a double-domed anti-reflective sapphire crystal, automatic 28,800 vph chronograph calibre, and ballistic Cordura strap.', 165000, null, false, true, false, array['/src/assets/images/zhar_luxury_watch_1794080536688.jpg']::text[], array['41mm Case']::text[], 4, 'ZHR-HOR-003', array['Grade 5 Titanium with Brushed Obsidian DLC','Double Anti-Reflective Scratchproof Sapphire Crystal','Water resistant to 100 meters (10 ATM)','70-hour power reserve automatic movement','Bespoke ballistic nylon & fluororubber deployant strap']::text[], 'Titanium Grade 5 & Sapphire Glass') on conflict (id) do nothing;
insert into public.products (id,name,slug,category,gender,description,price,original_price,is_sale,is_featured,is_new_arrival,images,sizes,stock,sku,details,materials) values ('prod-4', 'Sculptural Heavyweight French Terry Hoodie', 'sculptural-heavyweight-hoodie', 'Hoodies', 'Unisex', 'Crafted from custom 550 GSM custom-knit loopback French terry. Designed with an exaggerated drop shoulder, seamless kangaroo pocket, and double-layered structured hood that holds its sculptural posture effortlessly.', 24500, 28000, true, true, true, array['/src/assets/images/zhar_luxury_hoodie_1794080536443.jpg']::text[], array['XS','S','M','L','XL']::text[], 19, 'ZHR-HOD-004', array['550 GSM Organic Combed Loopback Cotton','Boxy drop-shoulder tailored silhouette','Seamless flat-lock reinforced stitching','Tonal debossed ZHĀR monogram at wrist cuff','Pre-shrunk vintage stone washed']::text[], '100% Organic Turkish Combed Cotton') on conflict (id) do nothing;
insert into public.products (id,name,slug,category,gender,description,price,original_price,is_sale,is_featured,is_new_arrival,images,sizes,stock,sku,details,materials) values ('prod-5', 'Architectural Minimalist Oversized T-Shirt', 'architectural-minimalist-t-shirt', 'T-Shirts', 'Unisex', 'An immaculate essential cut from 320 GSM heavy compact jersey cotton. Features a dense ribbed micro-collar, clean seamless hem, and structured drape that retains its silhouette without cling.', 14500, null, false, false, true, array['/src/assets/images/zhar_luxury_hoodie_1794080536443.jpg']::text[], array['S','M','L','XL']::text[], 25, 'ZHR-TEE-005', array['320 GSM Long-Staple Egyptian Cotton','High-density rib crew neckline','Subtle monochrome embroidered logo at hem','Machine wash gentle cold']::text[], '100% Giza Egyptian Cotton') on conflict (id) do nothing;
insert into public.products (id,name,slug,category,gender,description,price,original_price,is_sale,is_featured,is_new_arrival,images,sizes,stock,sku,details,materials) values ('prod-6', 'Monolithic Lug-Sole Derby Shoes', 'monolithic-lug-sole-derby', 'Shoes', 'Men', 'Handcrafted Goodyear welted derby shoes cut from polished black French box calf leather, seated upon an exaggerated lightweight Vibram commando sole.', 68000, 75000, true, true, false, array['/src/assets/images/zhar_luxury_jacket_1794080538698.jpg']::text[], array['40 EU','41 EU','42 EU','43 EU','44 EU']::text[], 6, 'ZHR-SHU-006', array['Full grain French Box Calfskin','Traditional 360-degree Goodyear welt construction','Ultralight Italian Vibram lug outsole','Calfskin lined interior with arch cushioning']::text[], 'French Calfskin & Vibram Compound') on conflict (id) do nothing;
insert into public.products (id,name,slug,category,gender,description,price,original_price,is_sale,is_featured,is_new_arrival,images,sizes,stock,sku,details,materials) values ('prod-7', 'Geometric Architectural Belt & Card Flap', 'geometric-belt-card-flap', 'Accessories', 'Women', 'Sculpted from vegetable-tanned Tuscan bridle leather with custom brushed palladium matte hardware. Includes an integrated detachable origami card pouch.', 21000, null, false, false, true, array['/src/assets/images/zhar_luxury_watch_1794080536688.jpg']::text[], array['One Size (Adjustable)']::text[], 12, 'ZHR-ACC-007', array['3.5mm Full-grain Tuscan bridle leather','Custom milled brushed ruthenium hardware','Detachable cardholder with 4 card slots','Hand-burnished waxed edges']::text[], 'Tuscan Bridle Leather & Ruthenium') on conflict (id) do nothing;
insert into public.products (id,name,slug,category,gender,description,price,original_price,is_sale,is_featured,is_new_arrival,images,sizes,stock,sku,details,materials) values ('prod-8', 'Cédre Blanc & Santal Room & Body Essence (150ml)', 'cedre-blanc-santal-essence', 'Perfumes', 'Women', 'An ethereal harmony of white cedar, Australian sandalwood, dry cardamom, and powdered iris. Crafted for personal scent or ambient interior misting.', 28000, null, false, false, true, array['/src/assets/images/zhar_luxury_perfume_1794080536268.jpg']::text[], array['150ml Flacon']::text[], 18, 'ZHR-FRG-008', array['Artisanal hydro-distilled cedar heart','Sustainable Australian Sandalwood album','Cruelty-free, vegan formulation','Heavy etched glass vessel with magnetic cap']::text[], 'Pure Essential Botanical Distillates') on conflict (id) do nothing;
